import { useCallback } from 'react';

import { EVENT_ACTIONS } from '@proton/shared/lib/constants';
import { wait } from '@proton/shared/lib/helpers/promise';

import { useEventManager } from '../../hooks';

export const interval = 5000;
export const maxPollingSteps = 5;

type PollEventOptions = {
    property?: string;
    action?: EVENT_ACTIONS;
};

/**
 * Poll event updates for a bounded period, optionally ending when a matching
 * property/action event is received through the event manager subscription.
 */
export const usePollEvents = () => {
    const eventManager = useEventManager();

    return useCallback(
        async ({ property, action }: PollEventOptions = {}) => {
            let finished = false;
            let unsubscribe = () => {};

            const finish = () => {
                if (finished) {
                    return;
                }
                finished = true;
                unsubscribe();
            };

            if (property !== undefined && action !== undefined) {
                unsubscribe = eventManager.subscribe((events: any) => {
                    if (finished || !events) {
                        return;
                    }

                    const updates = Array.isArray(events) ? events : [events];
                    const matched = updates.some(
                        (event) => event?.[property]?.Action === action || (event?.[property] && event?.Action === action)
                    );
                    if (matched) {
                        finish();
                    }
                });
            }

            try {
                for (let step = 0; step < maxPollingSteps && !finished; step++) {
                    await wait(interval);
                    if (finished) {
                        break;
                    }
                    await eventManager.call();
                }
            } finally {
                finish();
            }
        },
        [eventManager]
    );
};
